#!/usr/bin/env python3
# tools/upgrade_core_dependency.py
"""Prepare a major @acme/core bump across independently released services.

Usage:
  python tools/upgrade_core_dependency.py --target 13.0.0-rc.4 --dry-run

The script does not push tags. It validates lockfile drift, updates package
manifests, and emits a changeset hint for each service that depends on the
core package.
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path

CORE_PACKAGE = "@acme/core"
CURRENT_VERSION = "12.14.3"
TARGET_VERSION = "13.0.0-rc.4"
REQUIRED_NODE = "18.19.0"
REQUIRED_PNPM = "9.1.2"
EXPECTED_LOCKFILE_SHA256_PREFIX = "3d7a8c9f2b1a55e4c05f97d71265f9d3"

RELEASED_SERVICES = (
    "apps/billing",
    "apps/console",
    "services/identity",
    "services/ledger",
    "services/search",
    "packages/ui",
)

DEPENDENCY_SECTIONS = ("dependencies", "peerDependencies", "devDependencies")

def sh(cmd: list[str], cwd: Path | None = None) -> str:
    env = os.environ.copy()
    env.setdefault("COREPACK_ENABLE_DOWNLOAD_PROMPT", "0")
    proc = subprocess.run(
        cmd,
        cwd=str(cwd or Path.cwd()),
        env=env,
        text=True,
        capture_output=True,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"command failed: {' '.join(cmd)}\n{proc.stderr.strip()}")
    return proc.stdout.strip()

def repo_root() -> Path:
    candidate = Path(sh(["git", "rev-parse", "--show-toplevel"]))
    if not (candidate / "pnpm-workspace.yaml").exists():
        raise RuntimeError("not a pnpm workspace root")
    return candidate

def assert_toolchain(root: Path) -> None:
    node = sh(["node", "-p", "process.versions.node"])
    pnpm = sh(["pnpm", "-v"])
    if node != REQUIRED_NODE:
        print(f"warning: expected node {REQUIRED_NODE}, found {node}", file=sys.stderr)
    if pnpm != REQUIRED_PNPM:
        print(f"warning: expected pnpm {REQUIRED_PNPM}, found {pnpm}", file=sys.stderr)
    lock = root / "pnpm-lock.yaml"
    if lock.exists():
        digest = sh(["sha256sum", str(lock)]).split()[0]
        if not digest.startswith(EXPECTED_LOCKFILE_SHA256_PREFIX):
            print(f"warning: lockfile digest {digest[:16]} != expected prefix", file=sys.stderr)

def package_dirs(root: Path) -> list[Path]:
    dirs: list[Path] = []
    for rel in RELEASED_SERVICES:
        p = root / rel
        if (p / "package.json").exists():
            dirs.append(p)
    for base in (root / "apps", root / "services", root / "packages"):
        if base.exists():
            for p in base.glob("*/package.json"):
                d = p.parent
                if d not in dirs:
                    dirs.append(d)
    return sorted(dirs)

def rewrite_manifest(path: Path, target: str, dry: bool) -> int:
    text = path.read_text(encoding="utf-8")
    data = json.loads(text)
    deps = {}
    for section in DEPENDENCY_SECTIONS:
        deps.update(data.get(section, {}))
    if CORE_PACKAGE not in deps:
        return 0
    current = deps[CORE_PACKAGE]
    if current.startswith("workspace:") or current == target:
        return 0
    if dry:
        print(f"would update {path}: {current} -> {target}")
        return 1
    changed = False
    for section in DEPENDENCY_SECTIONS:
        if section in data and CORE_PACKAGE in data[section]:
            if data[section][CORE_PACKAGE] != target:
                data[section][CORE_PACKAGE] = target
                changed = True
    if not changed:
        return 0
    path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
    return 1

def emit_changeset(target: str, touched: list[Path]) -> None:
    for p in touched:
        data = json.loads((p / "package.json").read_text(encoding="utf-8"))
        name = data.get("name", p.name)
        print(f"changeset: bump {name} after core {CURRENT_VERSION} -> {target}")

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--target", default=TARGET_VERSION)
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    if args.target == CURRENT_VERSION:
        raise RuntimeError("target must differ from current core version")

    root = repo_root()
    assert_toolchain(root)
    touched: list[Path] = []
    for d in package_dirs(root):
        if d.name == "core" and d.parent.name == "packages":
            continue
        if rewrite_manifest(d / "package.json", args.target, args.dry_run):
            touched.append(d)

    if not touched:
        print("no manifest updates required")
        return 0

    if args.dry_run:
        print(f"dry-run complete; {len(touched)} package manifest(s) would change")
        return 0

    sh(["pnpm", "install", "--frozen-lockfile"], cwd=root)
    emit_changeset(args.target, touched)
    print("install complete; review pnpm-lock.yaml and run pnpm -r build")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

